    {b c : Finset ℤ} (hb : b ∈ bs) (hc : c ∈ cs) (x : ℤ) (hxb : x ∈ b) (hxc : x ∈ c)
    (hbc : b ≠ c) : bs ≠ cs

private theorem pairLoop_cons (x P : ℕ) (l : List ℕ) :
    pairLoop x (P :: l)
      = (if Nat.blt x P && Nat.blt P (x + x) then (P - x) :: pairLoop x l else pairLoop x l)

private theorem tripLoop_cons (x P : ℕ) (l : List ℕ) :
    tripLoop x (P :: l)
      = (if Nat.ble (x + 3) P && Nat.ble (P - x) (x + x) then (P - x) :: tripLoop x l
          else tripLoop x l)

private theorem candidates_cons (x a : ℕ) (t : List ℕ) :
    candidates x (a :: t)
      = (if memList a (pairNeeds x) then
            [x, a] :: candTrip x a t (candidates x t) (tripNeeds x)
          else candTrip x a t (candidates x t) (tripNeeds x))

private theorem candTrip_cons (x a : ℕ) (t : List ℕ) (ih : List (List ℕ)) (s : ℕ) (tn : List ℕ) :
    candTrip x a t ih (s :: tn)
      = (if Nat.blt a s && Nat.blt s (a + a) && memList (s - a) t then
            [x, a, s - a] :: candTrip x a t ih tn
          else candTrip x a t ih tn)

private theorem mem_candTrip {x a b : ℕ} {t : List ℕ} {ih : List (List ℕ)} {tn : List ℕ}
    (hs : a + b ∈ tn) (h1 : 0 < b) (h2 : b < a) (hb : memList b t = true) :
    [x, a, b] ∈ candTrip x a t ih tn

private theorem mem_candidates_triple {x a b : ℕ} {rest : List ℕ}
    (hsorted : rest.Pairwise (· > ·)) (ha : a ∈ rest) (hb : b ∈ rest) (hb0 : 0 < b) (hba : b < a)
    (hs : a + b ∈ tripNeeds x) : [x, a, b] ∈ candidates x rest

private theorem descent {c S : ℤ} (_hS : 0 ≤ S) (Lo : ℤ → Finset ℤ)
    (hsum : ∀ e : ℤ, S < e → e ≤ c → (Lo e).sum id = e)
    (hpos : ∀ e : ℤ, S < e → e ≤ c → ∀ y ∈ Lo e, (1 : ℤ) ≤ y)
    (hstep : ∀ x : ℤ, S < x → x ≤ c → ∃ e : ℤ, x ≤ e ∧ e ≤ c ∧ x ∈ Lo e) :
    ∀ e : ℤ, S < e → e ≤ c → Lo e = {e}

theorem toBlocksZ_ne_of_differZ {support : List ℤ} {bs cs : List (List ℤ)}
    (hb : framesOK support bs = true) (hc : framesOK support cs = true)
    (h : differZ bs cs = true) : toBlocksZ bs ≠ toBlocksZ cs

private theorem liftBlocks_eq (Q Q' : ℤ) (bs : Finset (Finset ℤ)) :
    liftBlocks Q Q' bs = bs.image (fun b => b.image (relabel Q Q')) ∪
      canonicalPairs Q' ((Q + 1) / 2) ((Q' - 1) / 2)

private theorem relabel_sum {Q Q' : ℤ} (hle : Q ≤ Q') (b : Finset ℤ) :
    (b.image (relabel Q Q')).sum id
      = b.sum id + (Q' - Q) * ((b.filter (fun y => (Q - 1) / 2 < y)).card : ℤ)

private theorem unrelabel_injOn {Q Q' : ℤ} {s : Finset ℤ} (hle : Q ≤ Q')
    (hs : ∀ y ∈ s, y ≤ (Q - 1) / 2 ∨ Q' - (Q - 1) / 2 ≤ y) :
    Set.InjOn (unrelabel Q Q') ↑s

private theorem unrelabel_sum {Q Q' : ℤ} {b : Finset ℤ} (hinj : Set.InjOn (unrelabel Q Q') ↑b) :
    (b.image (unrelabel Q Q')).sum id
      = b.sum id - (Q' - Q) * ((b.filter (fun y => (Q' - 1) / 2 < y)).card : ℤ)

private theorem relabel_image_unrelabel {Q Q' : ℤ} (hle : Q ≤ Q') {b : Finset ℤ}
    (hb : ∀ y ∈ b, y ≤ (Q - 1) / 2 ∨ Q' - (Q - 1) / 2 ≤ y) :
    (b.image (unrelabel Q Q')).image (relabel Q Q') = b

private theorem truncBlocks_eq (Q Q' : ℤ) (bs : Finset (Finset ℤ)) :
    truncBlocks Q Q' bs = (bs \ canonicalPairs Q' ((Q + 1) / 2) ((Q' - 1) / 2)).image
      (fun b => b.image (unrelabel Q Q'))

private theorem certificates_of_le_21 {k : ℤ} (hk : 4 ≤ k) (hk' : k ≤ 21) :
